loader.applyTools(provider, null, com.example.app.DocumentProcessor.class);

public final class com.example.tools.ProjectTools implements org.machanism.machai.process.tools.FunctionTools {
  @org.machanism.machai.process.tools.Tool(name = "echo", description = "Returns supplied text.")
  public java.lang.String echo(@org.machanism.machai.process.tools.Param(name = "text", description = "Text to return") java.lang.String text) { return text; }
}

org.machanism.machai.process.provider.ProcessProvider provider = org.machanism.machai.process.manager.ProcessProviderManager.getProvider("OpenAI:gpt-4o-mini", configurator);
